#!/bin/sh
# Generated by scripts/generate_muse_packages.py: Muse resolves any argv element
# containing '/' as a plugin file, so the server command runs from here.
exec sh -c 'token=$(gh auth token) || exit; export GH_MCP_AUTH="Bearer $token"; header=$(printf '"'"'Authorization:$%s'"'"' '"'"'{GH_MCP_AUTH}'"'"'); exec npx -y mcp-remote https://api.githubcopilot.com/mcp/ --header "$header"' "$@"
